from pysat.solvers import Glucose3
from pysat.card import CardEnc

# We have positions 0..31 (32 positions)
# Each value v (1..16) appears twice at positions i and i+v+1
# So for each v, we need to choose a starting position i such that i+v+1 < 32

n = 16
length = 32

# For each value v, possible starting positions
possible_starts = {}
for v in range(1, n+1):
    starts = []
    for i in range(length):
        j = i + v + 1
        if j < length:
            starts.append(i)
    possible_starts[v] = starts
    print(f"v={v}: {len(starts)} possible starts")

# Let's use a simpler approach - backtracking with constraint propagation
# Since we have fixed positions, let's try to solve it

# Fixed positions (0-indexed)
fixed = {
    5: 14,   # seq[5] = 14
    9: 4,    # seq[9] = 4
    11: 15,  # seq[11] = 15
    21: 9,   # seq[21] = 9
    26: 13,  # seq[26] = 13
    29: 10   # seq[29] = 10
}

print("Fixed positions:", fixed)

# Let's try a SAT approach
# Variables: for each value v and each possible start position i, a boolean variable
# But let's try a simpler backtracking first

def solve_langford(n, fixed_positions):
    length = 2 * n
    seq = [0] * length

    # Apply fixed positions
    for pos, val in fixed_positions.items():
        seq[pos] = val

    # For each value, track if placed and where
    placed = {}  # value -> (pos1, pos2) or None
    for v in range(1, n+1):
        placed[v] = None

    # Check if fixed positions are consistent
    for pos, val in fixed_positions.items():
        if placed[val] is None:
            placed[val] = [pos]
        else:
            placed[val].append(pos)

    # Verify fixed positions are consistent with spacing
    for v, positions in placed.items():
        if positions is not None and len(positions) == 2:
            p1, p2 = sorted(positions)
            if p2 - p1 != v + 1:
                print(f"Fixed positions for {v} are inconsistent: {p1}, {p2}, diff={p2-p1}, expected={v+1}")
                return None

    # Also check no conflicts in fixed positions
    for pos, val in fixed_positions.items():
        if seq[pos] != 0 and seq[pos] != val:
            print(f"Conflict at position {pos}")
            return None

    print("Initial seq:", seq)
    print("Placed so far:", placed)

    # Let's use a SAT solver approach with PySAT
    # For each value v, we have variables for each possible start position
    # Variable index: (v, start_pos) -> var_id

    solver = Glucose3()

    var_id = {}
    id_counter = 1

    for v in range(1, n+1):
        for start in possible_starts[v]:
            var_id[(v, start)] = id_counter
            id_counter += 1

    # Exactly one start position per value
    for v in range(1, n+1):
        vars_for_v = [var_id[(v, start)] for start in possible_starts[v]]
        if len(vars_for_v) > 0:
            # At least one
            solver.add_clause(vars_for_v)
            # At most one (pairwise)
            for i in range(len(vars_for_v)):
                for j in range(i+1, len(vars_for_v)):
                    solver.add_clause([-vars_for_v[i], -vars_for_v[j]])

    # Each position can have at most one value
    # For each position p, collect all (v, start) pairs that would place a value at p
    pos_to_vars = {p: [] for p in range(length)}
    for v in range(1, n+1):
        for start in possible_starts[v]:
            end = start + v + 1
            # Position start gets value v
            pos_to_vars[start].append(var_id[(v, start)])
            # Position end gets value v
            pos_to_vars[end].append(var_id[(v, start)])

    for p in range(length):
        vars_at_p = pos_to_vars[p]
        if len(vars_at_p) > 1:
            for i in range(len(vars_at_p)):
                for j in range(i+1, len(vars_at_p)):
                    solver.add_clause([-vars_at_p[i], -vars_at_p[j]])

    # Fixed positions
    for pos, val in fixed_positions.items():
        # Find which start positions place val at pos
        relevant_starts = []
        for start in possible_starts[val]:
            end = start + val + 1
            if start == pos or end == pos:
                relevant_starts.append(start)

        if len(relevant_starts) == 0:
            print(f"No valid start for fixed position {pos}={val}")
            return None

        # At least one of these starts must be chosen
        solver.add_clause([var_id[(val, s)] for s in relevant_starts])

    # Also, if a value is placed at a fixed position, the other position must be consistent
    # This is already handled by the position constraints

    print(f"Solving with {id_counter-1} variables...")
    result = solver.solve()

    if result:
        model = solver.get_model()
        # Extract solution
        seq = [0] * length
        for v in range(1, n+1):
            for start in possible_starts[v]:
                if var_id[(v, start)] in model and var_id[(v, start)] > 0:
                    end = start + v + 1
                    seq[start] = v
                    seq[end] = v
                    break

        # Verify
        for pos, val in fixed_positions.items():
            if seq[pos] != val:
                print(f"ERROR: Fixed position {pos} expected {val} but got {seq[pos]}")
                return None

        # Verify all positions filled
        if 0 in seq:
            print(f"ERROR: Some positions unfilled: {[i for i, v in enumerate(seq) if v==0]}")
            return None

        # Verify spacing
        for v in range(1, n+1):
            positions = [i for i, x in enumerate(seq) if x == v]
            if len(positions) != 2:
                print(f"ERROR: Value {v} appears {len(positions)} times")
                return None
            if positions[1] - positions[0] != v + 1:
                print(f"ERROR: Value {v} spacing is {positions[1]-positions[0]}, expected {v+1}")
                return None

        return seq
    else:
        print("UNSATISFIABLE")
        return None

result = solve_langford(n, fixed)
if result:
    print("Solution:", result)
else:
    print("No solution found")
